solution.solution.py:
import functools


def count_calls(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        wrapper.calls += 1
        return func(*args, **kwargs)
    wrapper.calls = 0
    return wrapper

unitTests:
@test("counts every call")
def _():
    @count_calls
    def square(x):
        """Squares x."""
        return x * x
    check_eq(square.calls, 0)
    check_eq(square(3), 9)
    check_eq(square(4), 16)
    check_eq(square.calls, 2)

@test("keeps the name and docstring")
def _():
    @count_calls
    def greet(name, punctuation="!"):
        """Says hello."""
        return f"hello {name}{punctuation}"
    check_eq(greet("Ada", punctuation="?"), "hello Ada?")
    check_eq(greet.__name__, "greet")
    check_eq(greet.__doc__, "Says hello.")

@test("each function has its own count")
def _():
    @count_calls
    def a():
        return 1
    @count_calls
    def b():
        return 2
    a(); a(); b()
    check_eq((a.calls, b.calls), (2, 1))

